tools.example:
// standalone application boot (no Linux)
the_ROM_image:
{
  [bootloader] fsbl.elf
  system.bit
  app.elf
}

// Linux boot with image.ub in the boot image (alternative to a separate file on SD)
the_ROM_image:
{
  [bootloader, destination_cpu=a53-0] fsbl.elf
  [pmufw_image] pmufw.elf
  [destination_device=pl] system.bit
  [destination_cpu=a53-0, exception_level=el-3, trustzone] bl31.elf
  [destination_cpu=a53-0, load=0x00100000] system.dtb
  [destination_cpu=a53-0, exception_level=el-2] u-boot.elf
}

tools.usage:
# Vitis templates that produce the firmware ELFs
app create -name fsbl -platform <plat> -domain <a53_std> -template {Zynq MP FSBL}
app create -name pmufw -platform <plat> -domain <pmu_std> -template {ZynqMP PMU Firmware}
app create -name plm -platform <versal_plat> -domain <pmc_std> -template {versal PLM}
# PetaLinux equivalents
petalinux-build -c fsbl ; -c pmufw ; -c arm-trusted-firmware ; -c u-boot ; -c kernel ; -c device-tree ; -c plm ; -c psmfw
petalinux-package --boot --format BIN --fsbl images/linux/zynqmp_fsbl.elf --pmufw images/linux/pmufw.elf --atf images/linux/bl31.elf --u-boot images/linux/u-boot.elf --fpga images/linux/system.bit --force

#include "xparameters.h"
#include "xgpio.h"
#include "xil_printf.h"
XGpio gpio;
int main(void) {
  XGpio_Config *cfg = XGpio_LookupConfig(XPAR_AXI_GPIO_0_DEVICE_ID);   // 2023.2+: XPAR_AXI_GPIO_0_BASEADDR
  XGpio_CfgInitialize(&gpio, cfg, cfg->BaseAddress);
  XGpio_SetDataDirection(&gpio, 1, 0x0);
  XGpio_DiscreteWrite(&gpio, 1, 0xA5);
  xil_printf("LEDs set: 0x%02x\r\n", XGpio_DiscreteRead(&gpio, 1));
  return 0;
}

